<?php

use Modules\Core\Models\User;use Modules\Finance\Models\AccountMapping;use Modules\Finance\Models\ArInvoice;use Modules\Finance\Models\FxRevaluationRun;use Modules\Finance\Models\Journal;use Modules\Finance\Services\FxRevaluationService;use Modules\Finance\Services\JournalService;use Modules\MasterData\Models\ChartOfAccount;use Modules\MasterData\Models\Currency;use Modules\MasterData\Models\Customer;use Modules\MasterData\Models\ExchangeRate;use Modules\Sales\Models\SalesOrder;
function stage10eAccount(string$code,string$type,string$normal):ChartOfAccount{return ChartOfAccount::create(['company_id'=>1,'code'=>$code.'-'.uniqid(),'name'=>$code,'type'=>$type,'normal_balance'=>$normal]);}function stage10eExposure(User$u,float$closing=16000):ArInvoice{$usd=Currency::create(['company_id'=>1,'code'=>'USD','name'=>'US Dollar']);ExchangeRate::create(['company_id'=>1,'currency_id'=>$usd->id,'rate_date'=>'2026-08-31','rate'=>$closing]);$c=Customer::create(['company_id'=>1,'code'=>'C-'.uniqid(),'name'=>'Buyer']);$so=SalesOrder::create(['company_id'=>1,'doc_no'=>'SO-'.uniqid(),'customer_id'=>$c->id,'order_date'=>'2026-08-01','status'=>'CLOSED','created_by'=>$u->id]);return ArInvoice::create(['company_id'=>1,'doc_no'=>'AR-'.uniqid(),'customer_id'=>$c->id,'sales_order_id'=>$so->id,'invoice_date'=>'2026-08-01','currency_id'=>$usd->id,'exchange_rate'=>15000,'subtotal_amount'=>100,'total_amount'=>100,'base_amount'=>1500000,'finance_finalized_at'=>now(),'status'=>'OPEN','created_by'=>$u->id]);}function stage10eMapping():void{$ar=stage10eAccount('AR','ASSET','DEBIT');$gain=stage10eAccount('FXG','REVENUE','CREDIT');AccountMapping::create(['company_id'=>1,'event'=>'AR_FX_REVALUE_GAIN','debit_account_id'=>$ar->id,'credit_account_id'=>$gain->id]);}
it('membuat revaluation snapshot dan jurnal idempotent',function(){$u=User::factory()->create(['company_id'=>1]);stage10eExposure($u);stage10eMapping();$svc=app(FxRevaluationService::class);$run=$svc->run(1,'2026-08',$u);expect($run->lines)->toHaveCount(1)->and((float)$run->lines[0]->foreign_outstanding)->toBe(100.0)->and((float)$run->lines[0]->gain_loss)->toBe(100000.0)->and($run->journals)->toHaveCount(1);$again=$svc->run(1,'2026-08',$u);expect($again->id)->toBe($run->id)->and(FxRevaluationRun::count())->toBe(1);});
it('menolak close period sebelum exposure FX direvaluasi',function(){$u=User::factory()->create(['company_id'=>1]);stage10eExposure($u);\Modules\Finance\Models\GlPeriod::create(['company_id'=>1,'period'=>'2026-08','status'=>'OPEN']);app(JournalService::class)->closePeriod(1,'2026-08',$u);})->throws(RuntimeException::class,'belum direvaluasi');
it('mendeteksi perubahan rate setelah run sebelum close',function(){$u=User::factory()->create(['company_id'=>1]);stage10eExposure($u);stage10eMapping();$run=app(FxRevaluationService::class)->run(1,'2026-08',$u);ExchangeRate::where('rate_date','2026-08-31')->update(['rate'=>17000]);app(JournalService::class)->closePeriod(1,'2026-08',$u);})->throws(RuntimeException::class,'berubah setelah revaluation');
it('reversal revaluation masuk hari pertama period berikutnya dan tidak ganda',function(){$u=User::factory()->create(['company_id'=>1]);stage10eExposure($u);stage10eMapping();$svc=app(FxRevaluationService::class);$run=$svc->run(1,'2026-08',$u);app(JournalService::class)->closePeriod(1,'2026-08',$u);$reversed=$svc->reverse($run,$u);$journal=$reversed->journals[0]->reversalJournal;expect($reversed->status)->toBe('REVERSED')->and($journal->period)->toBe('2026-09')->and($journal->journal_date->toDateString())->toBe('2026-09-01')->and($journal->reverses_journal_id)->toBe($run->journals[0]->journal_id);expect($svc->reverse($reversed,$u)->id)->toBe($run->id);});
